// Turns the Error Trigger payload into one ledger row.
// This workflow is the last line of defence, so nothing here may throw.
const j = $input.first().json ?? {};
const ex = j.execution ?? {};
const trg = j.trigger ?? {};          // present when the failing workflow's TRIGGER broke
const wf = j.workflow ?? {};
const err = ex.error ?? trg.error ?? {};

const message = String(err.message || err.description || 'Unknown error').slice(0, 2000);
const failedNode = ex.lastNodeExecuted || err.node?.name || (j.trigger ? 'trigger' : 'unknown');

// Mask the parts of a message that change between runs of the same bug,
// so "order 4812 after 3021ms" and "order 77 after 3950ms" group together.
function normalise(s) {
  return s
    .toLowerCase()
    .replace(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/g, '<uuid>')
    .replace(/\d{4}-\d{2}-\d{2}[t ]\d{2}:\d{2}(:\d{2}(\.\d+)?)?(z|[+-]\d{2}:?\d{2})?/g, '<ts>')
    .replace(/https?:\/\/\S+/g, '<url>')
    .replace(/[\w.+-]+@[\w-]+\.[\w.]+/g, '<email>')
    .replace(/\b(?=[0-9a-f]*\d)[0-9a-f]{8,}\b/g, '<hex>')
    .replace(/\d+(\.\d+)?/g, '<n>')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 300);
}

return [{ json: {
  signature: [wf.id || wf.name || 'unknown', failedNode, normalise(message)].join(' | '),
  workflow_id: wf.id ?? null,
  workflow_name: wf.name || 'unknown workflow',
  failed_node: failedNode,
  error_message: message,
  execution_id: ex.id ?? null,
  execution_url: ex.url ?? null,
  error_at: new Date(trg.error?.timestamp ?? Date.now()).toISOString(),
} }];

// Works whether or not the ledger write succeeded.
const s = $('Build signature').first().json;
const r = $input.first().json ?? {};
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const ledgerOk = r.recurrence_count !== undefined && r.recurrence_count !== null;
const count = ledgerOk ? Number(r.recurrence_count) : null;
// With "continue on error", a failed node outputs { message, error: {...} }.
const ledgerError = r.message || r.error?.message || (typeof r.error === 'string' ? r.error : 'no response');

const title = !ledgerOk ? '🔴 Workflow failed (ledger write failed)'
  : r.previous_status === 'fixed' ? '🟠 Regression: a failure marked fixed is back'
  : count > 1 ? '🔁 Repeat failure'
  : '🔴 New failure';

const lines = [
  `<b>${esc(title)}</b>`,
  '',
  `<b>Workflow:</b> ${esc(s.workflow_name)}`,
  `<b>Node:</b> ${esc(s.failed_node)}`,
  `<b>Error:</b> ${esc(s.error_message.slice(0, 500))}`,
  ledgerOk ? `<b>Seen:</b> ${count} time${count === 1 ? '' : 's'} (ledger #${r.id})`
           : `<b>Ledger:</b> ${esc(String(ledgerError).slice(0, 200))}`,
  s.execution_url ? `\n<a href="${esc(s.execution_url)}">Open execution ${esc(s.execution_id)}</a>` : null,
];
return [{ json: { text: lines.filter((l) => l !== null).join('\n') } }];
